", direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_minimal/simple-contact-form--framework-react--style-dark--validation-message-absent/claude-haiku-4.5__s4/form.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Create file', new_file_contents="class ContactForm {
    constructor(formSelector) {
        this.form = document.querySelector(formSelector);
        this.fields = {
            fullName: {
                element: this.form.querySelector('#fullName'),
                errorElement: this.form.querySelector('#fullNameError'),
                validate: this.validateRequired.bind(this)
            },
            email: {
                element: this.form.querySelector('#email'),
                errorElement: this.form.querySelector('#emailError'),
                validate: this.validateEmail.bind(this)
            },
            phone: {
                element: this.form.querySelector('#phone'),
                errorElement: this.form.querySelector('#phoneError'),
                validate: this.validatePhone.bind(this)
            }
        };

        this.init();
    }

    init() {
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));

        Object.values(this.fields).forEach(field => {
            field.element.addEventListener('blur', (e) => this.handleFieldBlur(e));
            field.element.addEventListener('input', (e) => this.handleFieldInput(e));
        });
    }

    handleFieldBlur(event) {
        const fieldName = event.target.name;
        this.validateField(fieldName);
    }

    handleFieldInput(event) {
        const fieldName = event.target.name;
        const field = this.fields[fieldName];

        if (field.element.classList.contains('error')) {
            this.validateField(fieldName);
        }
    }

    validateField(fieldName) {
        const field = this.fields[fieldName];
        const isValid = field.validate(field.element.value);

        if (isValid) {
            field.element.classList.remove('error');
            field.errorElement.textContent = '';
            return true;
        }

        return false;
    }

    validateRequired(value) {
        const trimmed = value.trim();
        if (!trimmed) {
            this.fields.fullName.errorElement.textContent = 'Full name is required';
            this.fields.fullName.element.classList.add('error');
            return false;
        }
        return true;
    }

    validateEmail(value) {
        const trimmed = value.trim();
        if (!trimmed) {
            this.fields.email.errorElement.textContent = 'Email address is required';
            this.fields.email.element.classList.add('error');
            return false;
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(trimmed)) {
            this.fields.email.errorElement.textContent = 'Please enter a valid email address';
            this.fields.email.element.classList.add('error');
            return false;
        }

        return true;
    }

    validatePhone(value) {
        if (!value.trim()) {
            return true;
        }

        const phoneRegex = /^[\d\-().\s+]+$/;
        if (!phoneRegex.test(value)) {
            this.fields.phone.errorElement.textContent = 'Please enter a valid phone number';
            this.fields.phone.element.classList.add('error');
            return false;
        }

        const digitsOnly = value.replace(/\D/g, '');
        if (digitsOnly.length < 10 || digitsOnly.length > 15) {
            this.fields.phone.errorElement.textContent = 'Phone number should contain 10-15 digits';
            this.fields.phone.element.classList.add('error');
            return false;
        }

        return true;
    }

    handleSubmit(event) {
        event.preventDefault();

        const fullNameValid = this.validateField('fullName');
        const emailValid = this.validateField('email');
        const phoneValid = this.validateField('phone');

        if (fullNameValid && emailValid && phoneValid) {
            this.submitForm();
        }
    }

    submitForm() {
        const formData = {
            fullName: this.fields.fullName.element.value.trim(),
            email: this.fields.email.element.value.trim(),
            phone: this.fields.phone.element.value.trim()
        };

        console.log('Form submitted:', formData);

        alert('Thank you for contacting us! We will get back to you soon.');

        this.form.reset();
        Object.values(this.fields).forEach(field => {
            field.element.classList.remove('error');
            field.errorElement.textContent = '';
        });
    }
