        Object.values(this.fields).forEach(field => {
            field.element.addEventListener('blur', (e) => this.handleFieldBlur(e));
            field.element.addEventListener('input', (e) => this.handleFieldInput(e));
        });
    }

    handleFieldBlur(event) {
        const fieldName = event.target.name;
        this.validateField(fieldName);
    }

    handleFieldInput(event) {
        const fieldName = event.target.name;
        const field = this.fields[fieldName];

        if (field.element.classList.contains('error')) {
            this.validateField(fieldName);
        }
    }

    validateField(fieldName) {
        const field = this.fields[fieldName];
        const isValid = field.validate(field.element.value);

        if (isValid) {
            field.element.classList.remove('error');
            field.errorElement.textContent = '';
            return true;
        }

        return false;
    }

    validateRequired(value) {
        const trimmed = value.trim();
        if (!trimmed) {
            this.fields.fullName.errorElement.textContent = 'Full name is required';
            this.fields.fullName.element.classList.add('error');
            return false;
        }
        return true;
    }

    validateEmail(value) {
        const trimmed = value.trim();
        if (!trimmed) {
            this.fields.email.errorElement.textContent = 'Email address is required';
            this.fields.email.element.classList.add('error');
            return false;
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(trimmed)) {
            this.fields.email.errorElement.textContent = 'Please enter a valid email address';
            this.fields.email.element.classList.add('error');
            return false;
        }

        return true;
    }

